INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q582948', 'Norse colonization of North America', 'The Norse settlement of North America, including Greenland, began in the late 10th century AD and lasted for about 500 years. Further west, the evidence is more limited.', 900, NULL, NULL, NULL, NULL, NULL, 'decade', '900s', 62, 'https://en.wikipedia.org/wiki/Norse_settlement_of_North_America'),
  ('Q2624975', 'Lachine massacre', 'The Lachine massacre, part of the Beaver Wars, occurred when 1,500 Mohawk warriors launched a surprise attack against the small (375 inhabitants) settlement of Lachine, New France, at the upper end of Montreal Island, on the morning of 5 August 1689. The attack was precipitated by the growing Haudenosaunee (Iroquois) frustration with the increased French incursions into their territory and the ongoing concern about French Marquis de Denonville''s attack of 1687, and it was encouraged by the settlers of New England as a way to leverage power against New France during King William''s War.', 1689, 8, 5, NULL, NULL, NULL, 'day', '5 August 1689', 45, 'https://en.wikipedia.org/wiki/Lachine_massacre'),
  ('Q1708064', 'Battle of Quebec', 'The Battle of Quebec was fought in October 1690 between the colonies of New France and Massachusetts Bay, then ruled by the kingdoms of France and England, respectively. It was the first time Quebec City''s defences were tested.', 1690, 10, 16, NULL, NULL, NULL, 'day', '16 October 1690', 50, 'https://en.wikipedia.org/wiki/Battle_of_Quebec_(1690)'),
  ('Q2890600', 'Battle of Hudson''s Bay', 'The Battle of Hudson''s Bay, also known as the Battle of York Factory, was a naval battle fought during the War of the Grand Alliance (known in England''s North American colonies as "King William''s War"). The battle took place on 5 September 1697, when a French warship commanded by Captain Pierre Le Moyne d''Iberville defeated an English squadron commanded by Captain John Fletcher.', 1697, 9, 5, NULL, NULL, NULL, 'day', '5 September 1697', 45, 'https://en.wikipedia.org/wiki/Battle_of_Hudson''s_Bay'),
  ('Q1735004', '1700 Cascadia earthquake', 'The 1700 Cascadia earthquake occurred along the Cascadia subduction zone on January 26, 1700, with an estimated moment magnitude of 8.7–9.2. The megathrust earthquake involved the Juan de Fuca plate from mid-Vancouver Island, south along the Pacific Northwest coast as far as northern California.', 1700, 1, 26, NULL, NULL, NULL, 'day', '26 January 1700', 56, 'https://en.wikipedia.org/wiki/1700_Cascadia_earthquake'),
  ('Q326028', 'Great Peace of Montreal', 'The Great Peace of Montreal (French: La Grande paix de Montréal) was a peace treaty between New France and 39 First Nations of North America that ended the Beaver Wars. It was signed on August 4, 1701, by Louis-Hector de Callière, governor of New France, and 1300 representatives of 39 Indigenous nations.', 1701, 8, 4, NULL, NULL, NULL, 'day', '4 August 1701', 53, 'https://en.wikipedia.org/wiki/Great_Peace_of_Montreal'),
  ('Q3078994', 'Siege of Port Royal', 'The siege of Port Royal (5–13 October 1710), also known as the Conquest of Acadia, was a military siege conducted by British regular and provincial forces under the command of Francis Nicholson against a French Acadian garrison and the Wabanaki Confederacy under the command of Daniel d''Auger de Subercase, at the Acadian capital, Port Royal. The successful British siege marked the beginning of permanent British control over the peninsular portion of Acadia, which had been referred to as Nova Scotia by the British since 1621.', 1710, 10, 5, 1710, 10, 13, 'day', '5 October 1710 – 13 October 1710', 43, 'https://en.wikipedia.org/wiki/Siege_of_Port_Royal_(1710)'),
  ('Q732992', 'Quebec Expedition', 'The Quebec expedition (also known as the Walker expedition to Quebec) was a British attempt to attack French-held Quebec City in mid-1711 during Queen Anne''s War, the North American theatre of the War of the Spanish Succession. It failed when seven troopships and one storeship were wrecked and 890 soldiers, sailors and women drowned in one of the worst naval disasters in British history.', 1711, 8, 22, NULL, NULL, NULL, 'day', '22 August 1711', 45, 'https://en.wikipedia.org/wiki/Quebec_expedition_(1711)'),
  ('Q517578', 'King George''s War', 'King George''s War (1744–1748) encompassed the military operations in North America that formed part of the War of the Austrian Succession (1740–1748). It was the third of the four French and Indian Wars.', 1744, NULL, NULL, 1748, NULL, NULL, 'year', '1744–1748', 61, 'https://en.wikipedia.org/wiki/King_George''s_War'),
  ('Q3118940', 'Father Le Loutre''s War', 'The conflicts in Nova Scotia, 1749–1755, were a series of escalating guerrilla campaigns in British-claimed Nova Scotia (then including present-day New Brunswick), beginning with the founding of Halifax in 1749 and ending with the British capture of Fort Beauséjour in June 1755. The conflicts were associated with Mi''kmaq and Wolastoqiyik resistance to British settlement on unceded territory, and the breakdown of Acadian neutrality under British demands for an unconditional oath of allegiance.', 1749, NULL, NULL, 1755, NULL, NULL, 'year', '1749–1755', 45, 'https://en.wikipedia.org/wiki/Conflicts_in_Nova_Scotia%2C_1749%E2%80%931755'),
  ('Q2888548', 'Battle of Fort Frontenac', 'The Battle of Fort Frontenac took place on August 26–28, 1758 during the Seven Years'' War (referred to as the French and Indian War in the United States) between France and Great Britain. The location of the battle was Fort Frontenac, a French fort and trading post which is located at the site of present-day Kingston, Ontario, at the eastern end of Lake Ontario where it drains into the St.', 1758, 8, 26, 1758, 8, 28, 'day', '26 August 1758 – 28 August 1758', 45, 'https://en.wikipedia.org/wiki/Battle_of_Fort_Frontenac'),
  ('Q3050672', 'Siege of Louisbourg', 'The siege of Louisbourg (8 June – 26 July 1758) was fought during the Seven Years'' War on Cape Breton Island between an attacking British force and defending French and Mi''kmaq troops. The French attempted to send reinforcements by sea, but were not able to as the fleet was blockaded and defeated by the British.', 1758, 6, 8, 1758, 7, 26, 'day', '8 June 1758 – 26 July 1758', 51, 'https://en.wikipedia.org/wiki/Siege_of_Louisbourg_(1758)'),
  ('Q311726', 'Battle of the Plains of Abraham', 'The Battle of the Plains of Abraham, also known as the First Battle of Quebec (French: Bataille des Plaines d''Abraham, Première bataille de Québec), was a pivotal battle in the Seven Years'' War—whose North American theatre is referred to by Americans as the French and Indian War. The battle, which took place on 13 September 1759, was fought by the British Army and Royal Navy against the French Army on the Promontory of Quebec, a plateau just outside the walls of Quebec City on land that was originally owned by a farmer named Abraham Martin, hence the name of the location.', 1759, 9, 13, NULL, NULL, NULL, 'day', '13 September 1759', 65, 'https://en.wikipedia.org/wiki/Battle_of_the_Plains_of_Abraham'),
  ('Q2659387', 'Battle of Beauport', 'The Battle of Beauport, also known as the Battle of Montmorency, fought on 31 July 1759, was an important confrontation between the British and French armed forces during the Seven Years'' War (also known as the French and Indian War and the War of Conquest) of the French province of Canada. The attack conducted by the British against the French defense line of Beauport, some 5 kilometres (3.1 mi) east of Quebec was checked, and the army of General James Wolfe retreated with 443 casualties and losses.', 1759, 7, 31, NULL, NULL, NULL, 'day', '31 July 1759', 48, 'https://en.wikipedia.org/wiki/Battle_of_Beauport'),
  ('Q689183', 'Battle of Sainte-Foy', 'The Battle of Sainte-Foy (French: Bataille de Sainte-Foy) sometimes called the Battle of Quebec (French: Bataille du Quebec), was fought on April 28, 1760, near the British-held town of Quebec in the French province of Canada during the Seven Years'' War (called the French and Indian War in the United States). It was a victory for the French under the Chevalier de Lévis over the British army under General Murray.', 1760, 4, 28, NULL, NULL, NULL, 'day', '28 April 1760', 51, 'https://en.wikipedia.org/wiki/Battle_of_Sainte-Foy'),
  ('Q251184', 'Battle of Signal Hill', 'The Battle of Signal Hill, fought on 15 September 1762, was the last battle of the Seven Years'' War. A British force under Lieutenant-colonel William Amherst recaptured St.', 1762, 9, 15, NULL, NULL, NULL, 'day', '15 September 1762', 53, 'https://en.wikipedia.org/wiki/Battle_of_Signal_Hill'),
  ('Q1779428', 'Siege of Fort St. Jean', 'The siege of Fort St. Jean (September 17 – November 3, 1775 French: Siège du Fort Saint-Jean) was conducted by American Brigadier General Richard Montgomery on the town and fort of Saint-Jean, also called St.', 1775, 9, 17, 1775, 11, 3, 'day', '17 September 1775 – 3 November 1775', 47, 'https://en.wikipedia.org/wiki/Siege_of_Fort_St._Jean'),
  ('Q1840117', 'Battle of Quebec', 'The Battle of Quebec (French: Bataille de Québec) was fought on December 31, 1775, between American Continental Army forces and the British defenders of Quebec City as part of the invasion of Quebec of the American Revolutionary War. The battle was the first major defeat of the war for the Americans, and it came with heavy losses.', 1775, 12, 31, NULL, NULL, NULL, 'day', '31 December 1775', 61, 'https://en.wikipedia.org/wiki/Battle_of_Quebec_(1775)'),
  ('Q1247957', 'Battle of Trois-Rivières', 'The Battle of Trois-Rivières was fought on June 8, 1776, during the American Revolutionary War. A British army under Quebec Governor Sir Guy Carleton defeated an attempt by units from the Continental Army under the command of Brigadier General William Thompson to stop a British advance up the Saint Lawrence River valley.', 1776, 6, 8, NULL, NULL, NULL, 'day', '8 June 1776', 52, 'https://en.wikipedia.org/wiki/Battle_of_Trois-Rivi%C3%A8res'),
  ('Q1779439', 'Battle of The Cedars', 'The Battle of the Cedars (French: Bataille des Cèdres) was a series of military confrontations in the early stages of the American Revolutionary War that occurred during the Continental Army''s invasion of Quebec, which began in September 1775. These skirmishes, which involved limited combat, occurred in May 1776 at and around the Cedars, 45 km (28 mi) west of Montreal, Quebec.', 1776, NULL, NULL, 1776, 5, 27, 'year', '1776', 47, 'https://en.wikipedia.org/wiki/Battle_of_the_Cedars'),
  ('Q200682', 'Battle of Queenston Heights', 'The Battle of Queenston Heights was the first major engagement of the War of 1812. The battle took place on 13 October 1812, at Queenston in Upper Canada (now Ontario) and was a decisive British victory.', 1812, 10, 13, NULL, NULL, NULL, 'day', '13 October 1812', 56, 'https://en.wikipedia.org/wiki/Battle_of_Queenston_Heights'),
  ('Q365640', 'Battle of Beaver Dams', 'The Battle of Beaver Dams took place on 24 June 1813, during the War of 1812. A column of troops from the United States Army marched from Fort George and attempted to surprise a British outpost at Beaver Dams, billeting themselves overnight in the village of Queenston, Ontario.', 1813, 6, 24, NULL, NULL, NULL, 'day', '24 June 1813', 47, 'https://en.wikipedia.org/wiki/Battle_of_Beaver_Dams'),
  ('Q645288', 'Battle of the Thames', 'The Battle of the Thames , also known as the Battle of Moraviantown, was an American victory over British forces and Tecumseh''s Confederacy during the War of 1812. The battle took place on October 5, 1813, in Upper Canada near what is now Thamesville, Ontario.', 1813, 10, 5, NULL, NULL, NULL, 'day', '5 October 1813', 56, 'https://en.wikipedia.org/wiki/Battle_of_the_Thames'),
  ('Q990715', 'Battle of Lake Erie', 'The Battle of Lake Erie, also known as the Battle of Put-in-Bay, was fought on 10 September 1813, on Lake Erie off the shores of Ohio during the War of 1812. Nine vessels of the United States Navy defeated and captured six vessels of the British Royal Navy.', 1813, 9, 10, NULL, NULL, NULL, 'day', '10 September 1813', 56, 'https://en.wikipedia.org/wiki/Battle_of_Lake_Erie'),
  ('Q1752783', 'Battle of the Chateauguay', 'The Battle of the Chateauguay was an engagement of the War of 1812. On 26 October 1813, a Canadian and Native force consisting of 1,530 militia and Mohawk warriors from Lower Canada, commanded by Charles de Salaberry, repelled an American force of about 2,600 regulars which was attempting to invade Lower Canada and ultimately attack Montreal.', 1813, 10, 26, NULL, NULL, NULL, 'day', '26 October 1813', 45, 'https://en.wikipedia.org/wiki/Battle_of_the_Chateauguay'),
  ('Q364322', 'Battle of Lundy''s Lane', 'The Battle of Lundy''s Lane, also known as the Battle of Niagara or contemporarily as the Battle of Bridgewater, was fought on 25 July 1814, during the War of 1812, between an invading American army and a British and Canadian army near present-day Niagara Falls, Ontario. It was one of the bloodiest battles of the war, and one of the deadliest battles fought in Canada, with approximately 1,720 casualties including 258 killed.', 1814, 7, 25, NULL, NULL, NULL, 'day', '25 July 1814', 45, 'https://en.wikipedia.org/wiki/Battle_of_Lundy''s_Lane'),
  ('Q1793109', 'Battle of Chippawa', 'The Battle of Chippawa (sometimes spelled Chippewa) was a War of 1812 battle fought on July 5, 1814, in which the United States Army defeated British forces during the American invasion of Upper Canada along the Niagara River. This battle and the subsequent Battle of Lundy''s Lane demonstrated that trained American troops could hold their own against British regulars.', 1814, 7, 5, NULL, NULL, NULL, 'day', '5 July 1814', 47, 'https://en.wikipedia.org/wiki/Battle_of_Chippawa'),
  ('Q1757487', 'Battle of Seven Oaks', 'The Battle of Seven Oaks—also known as the Seven Oaks Massacre and the Seven Oaks Incident—was a violent confrontation of the Pemmican War between the Hudson''s Bay Company (HBC) and the North West Company (NWC) which occurred on 19 June 1816 near modern-day Winnipeg, Manitoba. Resulting in a decisive victory for the NWC over their rivals in the North American fur trade, the confrontation was the climax in a long series of dispute in the Canadas.', 1816, 6, 19, NULL, NULL, NULL, 'day', '19 June 1816', 45, 'https://en.wikipedia.org/wiki/Battle_of_Seven_Oaks'),
  ('Q389091', 'Upper Canada Rebellion', 'The Upper Canada Rebellion was an insurrection against the oligarchic government of the British colony of Upper Canada (present-day Ontario) in December 1837. While public grievances had existed for years in Upper Canada, what emboldened rebels there to revolt was the rebellion which started the previous month in Lower Canada (present-day Quebec).', 1837, 12, NULL, NULL, NULL, NULL, 'month', 'December 1837', 43, 'https://en.wikipedia.org/wiki/Upper_Canada_Rebellion'),
  ('Q1560445', 'Rebellions of 1837', 'The Rebellions of 1837–1838 (French: Rébellions de 1837) were two armed uprisings that took place in Lower and Upper Canada in 1837 and 1838. Both rebellions were motivated by frustrations with lack of political reform.', 1837, 12, 7, 1838, 12, 4, 'day', '7 December 1837 – 4 December 1838', 52, 'https://en.wikipedia.org/wiki/Rebellions_of_1837%E2%80%931838'),
  ('Q2466441', 'Lower Canada Rebellion', 'The Lower Canada Rebellion (French: rébellion du Bas-Canada), commonly referred to as the Patriots'' Rebellion (Rébellion des patriotes) in French, is the name given to the armed conflict in 1837–38 between rebels and the British colonial government of Lower Canada (now southern Quebec). Together with the simultaneous rebellion in the neighbouring colony of Upper Canada (now southern Ontario), it formed the Rebellions of 1837–38 (rébellions de 1837–38).', 1837, 11, 6, 1838, 11, 10, 'day', '6 November 1837 – 10 November 1838', 43, 'https://en.wikipedia.org/wiki/Lower_Canada_Rebellion'),
  ('Q856168', 'Pastry War', 'The Pastry War began in November 1838 when French naval forces blockaded ports in Mexico, and captured San Juan de Ulúa in Veracruz. This was in response to allegations of mistreatment of French nationals in Mexico, including a pastry chef after whom the war was named, and ended in March 1839 with a British-brokered peace.', 1838, 11, 27, 1839, 3, 9, 'day', '27 November 1838 – 9 March 1839', 65, 'https://en.wikipedia.org/wiki/Pastry_War'),
  ('Q1052060', 'Cayuse War', 'The Cayuse War (1847–1855) was an armed conflict between the Cayuse people of the Northwestern United States and settlers, backed by the U.S. government. The conflict was triggered by the Whitman massacre of 1847, where the Cayuse attacked a missionary outpost in response to a deadly measles epidemic that they believed was caused by Marcus Whitman.', 1847, NULL, NULL, 1855, NULL, NULL, 'year', '1847–1855', 43, 'https://en.wikipedia.org/wiki/Cayuse_War'),
  ('Q2996302', 'Fenian raids', 'The Fenian raids were a series of incursions carried out by the Fenian Brotherhood, an Irish republican organization based in the United States, on military fortifications, customs posts, and other targets in Canada (called British North America until 1867) in 1866, and again from 1870 to 1871. A number of separate incursions by the Fenian Brotherhood into Canada were undertaken to bring pressure on the British government to withdraw from Ireland, although none of these raids achieved their aims.', 1866, 4, NULL, 1871, 10, NULL, 'month', 'April 1866 – October 1871', 51, 'https://en.wikipedia.org/wiki/Fenian_raids'),
  ('Q765499', 'Red River Rebellion', 'The Red River Rebellion (French: Rébellion de la rivière Rouge), also known as the Red River Resistance, Red River uprising, or First Riel Rebellion, was the sequence of events that led up to the 1869 establishment of a provisional government by Métis leader Louis Riel and his followers at the Red River Colony, in the early stages of establishing today''s Canadian province of Manitoba. It had earlier been a territory called Rupert''s Land and been under control of the Hudson''s Bay Company before it was sold.', 1869, 10, 11, NULL, NULL, NULL, 'day', '11 October 1869', 52, 'https://en.wikipedia.org/wiki/Red_River_Rebellion'),
  ('Q3119025', 'Red River War', 'The Red River War was a military campaign launched by the United States Army in 1874 to displace the Comanche, Kiowa, Southern Cheyenne, and Arapaho tribes from the Southern Plains, and forcibly relocate the tribes to reservations in Indian Territory. The war had several army columns crisscross the Texas Panhandle in an effort to locate, harass, and capture nomadic Native American bands.', 1874, NULL, NULL, 1875, NULL, NULL, 'year', '1874–1875', 41, 'https://en.wikipedia.org/wiki/Red_River_War'),
  ('Q1506788', 'North-West Rebellion', 'The North-West Rebellion (French: Rébellion du Nord-Ouest) was an armed rebellion of Métis under Louis Riel and an associated uprising of Cree and Assiniboine mostly in the District of Saskatchewan, against the Canadian government. Important events included the Frog Lake incident, and the capture of Batoche.', 1885, 6, 3, 1885, 6, 3, 'day', '3 June 1885', 51, 'https://en.wikipedia.org/wiki/North-West_Rebellion'),
  ('Q631489', 'Klondike Gold Rush', 'The Klondike Gold Rush was a migration by an estimated 100,000 prospectors to the Klondike region of Yukon in northwestern Canada, between 1896 and 1898. Gold was discovered there by local miners on August 16, 1896; when the news reached Seattle and San Francisco the following year, it triggered a stampede of prospectors.', 1896, NULL, NULL, 1899, NULL, NULL, 'year', '1896–1899', 72, 'https://en.wikipedia.org/wiki/Klondike_Gold_Rush'),
  ('Q502073', 'Halifax explosion', 'On the morning of 6 December 1917, the French cargo ship SS Mont-Blanc and the Norwegian vessel SS Imo collided in the harbour of Halifax, Nova Scotia, Canada. Laden with high explosives, Mont-Blanc caught fire and detonated, devastating the Richmond district of Halifax.', 1917, 12, 6, NULL, NULL, NULL, 'day', '6 December 1917', 71, 'https://en.wikipedia.org/wiki/Halifax_Explosion'),
  ('Q719883', 'Statute of Westminster 1931', 'The Statute of Westminster 1931 (22 & 23 Geo. 5.', 1931, NULL, NULL, NULL, NULL, NULL, 'year', '1931', 71, 'https://en.wikipedia.org/wiki/Statute_of_Westminster_1931'),
  ('Q4566797', '1950 British Columbia B-36 crash', 'Sometime after midnight on 14 February 1950, a Convair B-36B, United States Air Force Serial Number 44-92075 assigned to the US 7th Bombardment Wing, Heavy at Carswell Air Force Base in Texas, crashed in northwestern British Columbia on Mount Kologet after jettisoning a Mark 4 nuclear bomb. This was the first such nuclear weapon loss in history.', 1950, 2, 13, NULL, NULL, NULL, 'day', '13 February 1950', 45, 'https://en.wikipedia.org/wiki/1950_British_Columbia_B-36_crash'),
  ('Q2186383', 'Bed-Ins For Peace', 'A bed-in is a nonviolent protest against wars, initiated by Yoko Ono and her husband John Lennon during a two week period in Amsterdam and Montreal as an experimental test of new ways to promote peace. As the Vietnam War raged in 1969, artists Ono and Lennon held one bed-in protest at the Hilton Hotel in Amsterdam and one at the Queen Elizabeth Hotel in Montreal.', 1969, NULL, NULL, 1969, 6, 1, 'year', '1969', 57, 'https://en.wikipedia.org/wiki/Bed-in'),
  ('Q2746913', 'Air Canada Flight 621', 'On July 5, 1970, Air Canada Flight 621, a Douglas DC-8 registered as CF-TIW, was flying from Montréal–Dorval International Airport, Quebec, Canada, to Los Angeles International Airport, California, United States, via Toronto International Airport, Ontario, Canada. During landing at Toronto, the aircraft touched down hard, which ruptured the right fuel tanks.', 1970, 7, 5, NULL, NULL, NULL, 'day', '5 July 1970', 50, 'https://en.wikipedia.org/wiki/Air_Canada_Flight_621'),
  ('Q7122767', 'Pacific Western Airlines Flight 314', 'On 11 February 1978, Pacific Western Airlines Flight 314, a Boeing 737-200, crashed at Cranbrook/Canadian Rockies International Airport, near Cranbrook, British Columbia, Canada, killing 43 of the 49 people on board. The scheduled flight from Fort McMurray International Airport to Castlegar Airport via Edmonton, Alberta, Calgary, Alberta and Cranbrook, British Columbia crashed after its thrust reversers did not fully stow following an aborted landing to avoid a snowplow on the runway.', 1978, 2, 11, NULL, NULL, NULL, 'day', '11 February 1978', 47, 'https://en.wikipedia.org/wiki/Pacific_Western_Airlines_Flight_314'),
  ('Q1230986', 'Patriation', 'Patriation is the political process that led to full Canadian sovereignty, culminating with the Constitution Act, 1982. The process was necessary because, at the time, under the Statute of Westminster, 1931, and with Canada''s agreement, the British Parliament retained the power to amend Canada''s British North America Acts and to enact, more generally, for Canada at the request and with the consent of the Dominion.', 1982, 4, 17, NULL, NULL, NULL, 'day', '17 April 1982', 39, 'https://en.wikipedia.org/wiki/Patriation'),
  ('Q7122768', 'Pacific Western Airlines Flight 501', 'Pacific Western Airlines Flight 501 was a regularly scheduled flight from Calgary to Edmonton, Alberta, Canada. The Boeing 737-200 caught fire during takeoff on March 22, 1984.', 1984, 3, 22, NULL, NULL, NULL, 'day', '22 March 1984', 45, 'https://en.wikipedia.org/wiki/Pacific_Western_Airlines_Flight_501'),
  ('Q3180238', 'Arrow Air Flight 1285R', 'Arrow Air Flight 1285R was an international charter flight carrying U.S. Army personnel from Cairo, Egypt, to their home base in Fort Campbell, Kentucky, US, via Cologne, West Germany, and Gander, Newfoundland. On the morning of Thursday, 12 December 1985, shortly after takeoff from Canada''s Gander International Airport en route to Fort Campbell, the Douglas DC-8 serving the flight stalled, crashed, and burned about half a mile from the runway, killing all 248 passengers and 8 crew members on board.', 1985, 12, 12, NULL, NULL, NULL, 'day', '12 December 1985', 57, 'https://en.wikipedia.org/wiki/Arrow_Air_Flight_1285R'),
  ('Q219438', 'Montreal Protocol', 'The Montreal Protocol, officially the Montreal Protocol on Substances That Deplete the Ozone Layer, is an international treaty designed to protect the ozone layer by phasing out the production of numerous substances that are responsible for ozone depletion. It was agreed on 16 September 1987, and was entered into force on 1 January 1989.', 1987, 9, 16, NULL, NULL, NULL, 'day', '16 September 1987', 73, 'https://en.wikipedia.org/wiki/Montreal_Protocol'),
  ('Q2632428', 'Air Ontario Flight 1363', 'Air Ontario Flight 1363 was a scheduled Air Ontario passenger flight which crashed near Dryden, Ontario, Canada, on 10 March 1989 shortly after takeoff from Dryden Regional Airport. The aircraft was a Fokker F28-1000 Fellowship twin jet.', 1989, 3, 10, NULL, NULL, NULL, 'day', '10 March 1989', 53, 'https://en.wikipedia.org/wiki/Air_Ontario_Flight_1363'),
  ('Q570224', 'Ottawa Treaty', 'The Convention on the Prohibition of the Use, Stockpiling, Production and Transfer of Anti-Personnel Mines and on their Destruction of 1997, known informally as the Ottawa Treaty, the Anti-Personnel Mine Ban Convention, or often simply the Mine Ban Treaty, aims at eliminating anti-personnel landmines (APLs) around the world. By August 2025, 162 states had ratified or acceded to the treaty.', 1997, 12, 3, NULL, NULL, NULL, 'day', '3 December 1997', 70, 'https://en.wikipedia.org/wiki/Ottawa_Treaty'),
  ('Q461911', 'Swissair Flight 111', 'Swissair Flight 111 was a scheduled international passenger flight from John F. Kennedy International Airport in New York City, United States, to Cointrin Airport in Geneva, Switzerland. The flight was also a codeshare flight with Delta Air Lines.', 1998, 9, 2, NULL, NULL, NULL, 'day', '2 September 1998', 64, 'https://en.wikipedia.org/wiki/Swissair_Flight_111'),
  ('Q14875706', 'MK Airlines Flight 1602', 'MK Airlines Flight 1602 was an MK Airlines Boeing 747-200 cargo aircraft en route from Halifax Stanfield International Airport, Nova Scotia, Canada, to Zaragoza Airport, Spain. On 14 October 2004, it crashed on take-off from Halifax, killing the crew of 7.', 2004, 10, 14, NULL, NULL, NULL, 'day', '14 October 2004', 50, 'https://en.wikipedia.org/wiki/MK_Airlines_Flight_1602'),
  ('Q406503', 'Air France Flight 358', 'Air France Flight 358 was a regularly scheduled international flight from Charles de Gaulle Airport in Paris, France, to Toronto Pearson International Airport in Ontario, Canada. On the afternoon of 2 August 2005, while landing at Pearson airport, the Airbus A340 operating the route overran the runway and crashed into nearby Etobicoke Creek, approximately 300 m (1,000 ft) beyond the end of the runway.', 2005, 8, 2, NULL, NULL, NULL, 'day', '2 August 2005', 61, 'https://en.wikipedia.org/wiki/Air_France_Flight_358'),
  ('Q192135', 'Anti-Counterfeiting Trade Agreement', 'The Anti-Counterfeiting Trade Agreement (ACTA) is a multilateral treaty for the purpose of establishing international standards for intellectual property rights enforcement that did not enter into force. The agreement aims to establish an international legal framework for targeting counterfeit goods, generic medicines and copyright infringement on the Internet, and would create a new governing body outside existing forums, such as the World Trade Organization, the World Intellectual Property Organization, and the United Nations.', 2006, NULL, NULL, NULL, NULL, NULL, 'year', '2006', 73, 'https://en.wikipedia.org/wiki/Anti-Counterfeiting_Trade_Agreement'),
  ('Q947605', 'First Air Flight 6560', 'First Air Flight 6560 was a domestic charter flight that crashed on landing at Resolute, Nunavut, Canada, on 20 August 2011. Of the fifteen people on board, twelve were killed and the remaining three were severely injured.', 2011, 8, 20, NULL, NULL, NULL, 'day', '20 August 2011', 50, 'https://en.wikipedia.org/wiki/First_Air_Flight_6560'),
  ('Q1357510', '2012 Quebec student protests', 'The 2012 Quebec student protests (movement) were a series of student protests led by students individually such as the Association pour une solidarité syndicale étudiante (ASSÉ), the Fédération étudiante universitaire du Québec, and the Fédération étudiante collégiale du Québec against a proposal by the Quebec Cabinet, headed by Liberal Premier Jean Charest, to raise university tuition from $2,168 to $3,793 between 2012 and 2018. As part of the protest movement, a series of widespread student strikes were organized, involving half of Quebec''s student population by April 2012.', 2012, NULL, NULL, 2012, 9, 7, 'year', '2012', 50, 'https://en.wikipedia.org/wiki/2012_Quebec_student_protests'),
  ('Q28549976', '2017 Quebec City mosque shooting', 'On the evening of January 29, 2017, an Islamophobic domestic terrorist attack took place at the Islamic Cultural Centre of Quebec City, a mosque in the Sainte-Foy neighbourhood of Quebec City, Canada. Six worshippers were killed and five others seriously injured after evening prayers when the gunman entered the prayer hall shortly before 8:00 pm and opened fire for about two minutes with a semi-automatic pistol.', 2017, 1, 29, NULL, NULL, NULL, 'day', '29 January 2017', 65, 'https://en.wikipedia.org/wiki/Quebec_City_mosque_shooting'),
  ('Q58805164', 'Yellow vests movement', 'The yellow vest movement (French: Mouvement des gilets jaunes, pronounced [muvmɑ̃ de ʒilɛ ʒon]) refers to those involved in a series of populist, grassroots weekly protests in France that began on 17 November 2018 and ended on 28 June 2020. After an online petition posted in May 2018 had attracted nearly one million signatures, mass demonstrations began on 17 November.', 2018, 11, 17, NULL, NULL, NULL, 'day', '17 November 2018', 80, 'https://en.wikipedia.org/wiki/Yellow_vests_protests'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q110685226', 'Canada convoy protest', 'The Freedom Convoy (French: Convoi de la liberté), was a series of protests and blockades across Canada in early 2022, initially organized to oppose COVID-19 vaccine mandates for cross-border truck drivers. The movement quickly expanded to protest all COVID-19 restrictions and mandates.', 2022, 1, 22, NULL, NULL, NULL, 'day', '22 January 2022', 61, 'https://en.wikipedia.org/wiki/Freedom_Convoy');
